import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";

/** Recognized / reliable AI & tech news publishers */
const TRUSTED_HOSTS = [
  "techcrunch.com",
  "theverge.com",
  "reuters.com",
  "bloomberg.com",
  "wired.com",
  "arstechnica.com",
  "venturebeat.com",
  "axios.com",
  "semafor.com",
  "cnbc.com",
  "bbc.com",
  "bbc.co.uk",
  "ft.com",
  "wsj.com",
  "forbes.com",
  "nature.com",
  "science.org",
  "mit.edu",
