];

const LISTING_PATH_HINTS = [
  "/news$",
  "/news/$",
  "/blog$",
  "/blog/$",
  "/tag/",
  "/tags/",
  "/category/",
  "/topics/",
  "/latest/?$",
  "/updates/?$",
  "/artificial-intelligence/?$",
  "/technology/artificial-intelligence/?$",
];

function todayParis(): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "Europe/Paris",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date());
}

function hostOf(url: string): string | null {
  try {
    return new URL(url).hostname.replace(/^www\./, "").toLowerCase();
  } catch {
    return null;
  }
}

function isTrusted(url: string): boolean {
  const host = hostOf(url);
  if (!host) return false;
  return TRUSTED_HOSTS.some((h) => host === h || host.endsWith(`.${h}`));
}

function looksLikeListing(url: string): boolean {
  try {
    const u = new URL(url);
    const path = u.pathname.toLowerCase();
    if (path === "/" || path === "") return true;
    return LISTING_PATH_HINTS.some((re) => new RegExp(re, "i").test(path));
  } catch {
    return true;
  }
}

function inferKind(title: string, description: string, eventKind?: string): string {
  if (eventKind && ["pricing", "release", "business", "news", "research"].includes(eventKind)) {
    return eventKind === "research" ? "news" : eventKind;
  }
  const t = `${title} ${description}`.toLowerCase();
  if (/pric|plan|billing|free tier/.test(t)) return "pricing";
  if (/launch|releas|announce|introduc|unveil/.test(t)) return "release";
  if (/acquisit|fund|rais|ipo/.test(t)) return "business";
  return "news";
}

function buildQueries(today: string): string[] {
  const sites = [
    "site:techcrunch.com",
    "site:theverge.com",
    "site:reuters.com",
    "site:bloomberg.com",
    "site:wired.com",
    "site:arstechnica.com",
    "site:venturebeat.com",
    "site:openai.com",
    "site:anthropic.com",
    "site:blog.google",
    "site:huggingface.co/blog",
    "site:nvidia.com",
  ];
  return [
    `(${sites.slice(0, 6).join(" OR ")}) AI (launch OR release OR announce OR model OR GPT OR Claude) after:${today}`,
    `(${sites.slice(6).join(" OR ")}) AI (launch OR release OR announce OR update) after:${today}`,
    `AI tool OR model launch announcement ${today}`,
    `"AI" (released OR launches OR unveils OR announces) ${today}`,
  ];
}

async function readSecret(supabase: SupabaseClient, keys: string[]): Promise<string | null> {
  for (const key of keys) {
    const fromEnv = Deno.env.get(key);
    if (fromEnv) return fromEnv;
  }
  for (const key of keys) {
    const { data } = await supabase.from("runtime_secrets").select("value").eq("key", key).maybeSingle();
    if (data?.value) return data.value as string;
  }
  return null;
}

async function reformulateNews(
  supabase: SupabaseClient,
  input: {
    title: string;
    summary: string;
    markdown: string | null;
    source_url: string;
    product_names?: string[];
  },
): Promise<{ title: string; summary: string; body: string } | null> {
  const grokKey = await readSecret(supabase, ["GROK_API_KEY", "XAI_API_KEY"]);
  if (!grokKey) return null;
  const model =
    Deno.env.get("GROK_MODEL") ??
    (await readSecret(supabase, ["GROK_MODEL"])) ??
    "grok-4.20-0309-non-reasoning";

  const system = [
    "You are an editor for an AI Discovery catalog (Latest news).",
    "Rewrite the source article into a short, neutral product-news item.",
    "HARD RULES:",
    "1) Use ONLY facts present in the provided source text. Never invent.",
    "2) Focus on AI tools, models, APIs, agents, or platforms when possible.",
    "3) No hype, no affiliate tone, no speculation.",
    "4) Reply in English.",
    "OUTPUT ONLY valid JSON:",
    '{"title":"max 90 chars","summary":"1-2 sentences max 280 chars","body":"2-4 short paragraphs"}',
  ].join("\n");

  const excerpt = (input.markdown ?? input.summary).slice(0, 6000);
  const res = await fetch("https://api.x.ai/v1/chat/completions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${grokKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      max_tokens: 700,
      messages: [
        { role: "system", content: system },
        {
          role: "user",
          content: JSON.stringify({
            source_url: input.source_url,
            source_title: input.title,
            source_summary: input.summary,
            products: input.product_names ?? [],
            article_excerpt: excerpt,
          }),
        },
      ],
    }),
  });

  if (!res.ok) {
    console.error("Grok reformulate failed", res.status, await res.text());
    return null;
  }
  const body = await res.json();
  const content = body?.choices?.[0]?.message?.content;
  if (typeof content !== "string") return null;

  const match = content.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[0]) as { title?: string; summary?: string; body?: string };
    const title = (parsed.title ?? "").trim().slice(0, 180);
    const summary = (parsed.summary ?? "").trim().slice(0, 400);
    const articleBody = (parsed.body ?? "").trim().slice(0, 4000);
    if (!title || !summary) return null;
    return { title, summary, body: articleBody || summary };
  } catch {
    return null;
  }
}

async function matchSolutionSlug(
  supabase: SupabaseClient,
  productNames: string[] | undefined,
  text: string,
): Promise<string | null> {
  const { data: tools } = await supabase.from("tools").select("slug,name").eq("status", "published").limit(800);
  if (!tools?.length) return null;
  const hay = `${(productNames ?? []).join(" ")} ${text}`.toLowerCase();
  let best: { slug: string; score: number } | null = null;
  for (const t of tools) {
    const name = String(t.name ?? "").toLowerCase();
    const slug = String(t.slug ?? "");
    if (!name || name.length < 3) continue;
    if (hay.includes(name) || hay.includes(slug.replace(/-/g, " "))) {
      const score = name.length;
      if (!best || score > best.score) best = { slug, score };
    }
  }
  return best?.slug ?? null;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  try {
    if (req.method !== "POST") return jsonResponse({ error: "Method not allowed" }, 405);

    const body = (await req.json().catch(() => ({}))) as {
      publish?: boolean;
      limit?: number;
      days?: number;
    };
    const publish = Boolean(body.publish);
    const limit = Math.max(1, Math.min(Number(body.limit ?? 12), 20));
    const daysWindow = Math.max(1, Math.min(Number(body.days ?? 1), 3));

    const cronHeader = req.headers.get("x-ingest-secret");
    let supabase: SupabaseClient;
    if (cronHeader) {
      supabase = serviceClient();
      await assertCronSecret(req, supabase);
    } else {
      const auth = await requireStaff(req.headers.get("Authorization"));
      supabase = auth.service;
    }

    const today = todayParis();
    const allowedDates = new Set<string>();
    for (let i = 0; i < daysWindow; i++) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      allowedDates.add(
        new Intl.DateTimeFormat("en-CA", {
          timeZone: "Europe/Paris",
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
        }).format(d),
      );
    }

    const queries = buildQueries(today);
    const hits: Array<{ url: string; title?: string; description?: string }> = [];
    for (const query of queries) {
      try {
        const found = await searchNewTools(query, 6, supabase, { tbs: "qdr:d" });
        hits.push(...found);
      } catch (err) {
        console.error("search failed", query, err);
      }
    }

    const unique = new Map<string, { url: string; title?: string; description?: string }>();
    for (const hit of hits) {
      if (!hit.url) continue;
      let normalized: string;
      try {
        normalized = normalizeUrl(hit.url);
      } catch {
        continue;
      }
      if (!isTrusted(normalized)) continue;
      if (looksLikeListing(normalized)) continue;
      const key = normalized.replace(/\/+$/, "").toLowerCase();
      if (!unique.has(key)) unique.set(key, { ...hit, url: normalized });
    }

    const candidates = [...unique.values()].slice(0, limit);
    let created = 0;
    let skipped = 0;
    let stale = 0;
    let untrusted = 0;
    let listing = 0;
    let errors = 0;
    let reformulated = 0;
    const results: Array<{ url: string; status: string; id?: string; error?: string }> = [];

    // Count pre-filtered for transparency
    for (const hit of hits) {
      if (!hit.url) continue;
      try {
        const n = normalizeUrl(hit.url);
        if (!isTrusted(n)) untrusted += 1;
        else if (looksLikeListing(n)) listing += 1;
      } catch {
        untrusted += 1;
      }
    }

    for (const hit of candidates) {
      try {
        const { data: existing } = await supabase
          .from("news_items")
          .select("id")
          .eq("source_url", hit.url)
          .maybeSingle();
        if (existing) {
          skipped += 1;
          results.push({ url: hit.url, status: "exists", id: existing.id });
          continue;
        }

        const scraped = await scrapeNewsArticle(hit.url, supabase);
        if (scraped.is_article === false || looksLikeListing(hit.url)) {
          listing += 1;
          results.push({ url: hit.url, status: "listing" });
          continue;
        }

        const articleDate = scraped.published_date?.slice(0, 10);
        if (articleDate && !allowedDates.has(articleDate)) {
          stale += 1;
          results.push({ url: hit.url, status: "stale", error: `published ${articleDate}` });
          continue;
        }
        // If no date found, only keep when daysWindow > 1; for same-day strict, skip undated
        if (!articleDate && daysWindow <= 1) {
          stale += 1;
          results.push({ url: hit.url, status: "undated" });
          continue;
        }

        const rawTitle = (scraped.title || hit.title || hostOf(hit.url) || "AI update").trim().slice(0, 180);
        const rawSummary = (scraped.summary || hit.description || rawTitle).trim().slice(0, 400);

        const rewritten = await reformulateNews(supabase, {
          title: rawTitle,
          summary: rawSummary,
          markdown: scraped.markdown,
          source_url: hit.url,
          product_names: scraped.product_names,
        });
        if (rewritten) reformulated += 1;

        const title = (rewritten?.title || rawTitle).slice(0, 180);
        const summary = (rewritten?.summary || rawSummary).slice(0, 400);
        const articleBody = rewritten?.body || scraped.markdown?.slice(0, 2500) || null;

        let slug = slugify(title) || slugify(hostOf(hit.url) || "news");
        if (slug) {
          const { data: clash } = await supabase.from("news_items").select("id").eq("slug", slug).maybeSingle();
          if (clash) slug = `${slug}-${crypto.randomUUID().slice(0, 6)}`;
        }

        const solutionSlug = await matchSolutionSlug(
          supabase,
          scraped.product_names,
          `${title} ${summary}`,
        );

        const publishedAt = articleDate || today;
        const { data: row, error } = await supabase
          .from("news_items")
          .insert({
            title,
            slug: slug || null,
            summary,
            body: articleBody,
            kind: inferKind(title, summary, scraped.event_kind),
            event_type: rewritten ? "discovered_reformulated" : "discovered",
            published_at: publishedAt,
            source_url: hit.url,
            solution_slug: solutionSlug,
            status: publish ? "published" : "draft",
          })
          .select("id")
          .single();
        if (error) throw new Error(error.message);

        if (solutionSlug && row?.id) {
          const { data: tool } = await supabase
            .from("tools")
            .select("id")
            .eq("slug", solutionSlug)
            .maybeSingle();
          if (tool?.id) {
            await supabase.from("news_tool_links").upsert({
              news_item_id: row.id,
              tool_id: tool.id,
            });
          }
        }

        created += 1;
        results.push({
          url: hit.url,
          status: publish ? "published" : "draft",
          id: row.id,
        });
      } catch (err) {
        errors += 1;
        results.push({
          url: hit.url,
          status: "error",
          error: err instanceof Error ? err.message : "failed",
        });
      }
    }

    return jsonResponse({
      ok: true,
      stats: {
        day: today,
        days_window: daysWindow,
        searched_queries: queries.length,
        urls_found: hits.length,
        considered: candidates.length,
        created,
        skipped,
        stale,
        untrusted,
        listing,
        reformulated,
        errors,
        status: publish ? "published" : "draft",
      },
      results,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "discover-news failed";
    const status =
      message.includes("Invalid cron") || message.includes("Forbidden")
        ? 403
        : message.includes("Unauthorized")
          ? 401
          : 500;
    return jsonResponse({ error: message }, status);
  }
});

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-ingest-secret",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

export function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";

export function serviceClient(): SupabaseClient {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export function userClient(authHeader: string): SupabaseClient {
  const url = Deno.env.get("SUPABASE_URL");
  const anon = Deno.env.get("SUPABASE_ANON_KEY");
  if (!url || !anon) throw new Error("Missing SUPABASE_URL or SUPABASE_ANON_KEY");
  return createClient(url, anon, {
    global: { headers: { Authorization: authHeader } },
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export async function requireStaff(authHeader: string | null) {
  if (!authHeader) throw new Error("Missing Authorization header");
  const supabase = userClient(authHeader);
  const { data: userData, error: userError } = await supabase.auth.getUser();
  if (userError || !userData.user) throw new Error("Unauthorized");

  const { data: profile, error: profileError } = await supabase
    .from("profiles")
    .select("id, role, email")
    .eq("id", userData.user.id)
    .maybeSingle();

  if (profileError) throw new Error(profileError.message);
  if (!profile || !["editor", "admin", "owner"].includes(profile.role)) {
    throw new Error("Forbidden: staff role required");
  }

  return { supabase, user: userData.user, profile, service: serviceClient() };
}

export async function runtimeSecret(supabase: SupabaseClient, key: string) {
  const fromEnv = Deno.env.get(key);
  if (fromEnv) return fromEnv;
  const { data, error } = await supabase.from("runtime_secrets").select("value").eq("key", key).maybeSingle();
  if (error) throw new Error(error.message);
  if (!data?.value) throw new Error(`${key} secret is not set`);
  return data.value as string;
}

export async function assertCronSecret(req: Request, supabase?: SupabaseClient) {
  const client = supabase ?? serviceClient();
  const expected = await runtimeSecret(client, "INGEST_CRON_SECRET");
  const provided = req.headers.get("x-ingest-secret");
  if (!provided || provided !== expected) throw new Error("Invalid cron secret");
}

export function normalizeUrl(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Empty URL");
  const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
  const u = new URL(withProtocol);
  u.hash = "";
  u.hostname = u.hostname.toLowerCase();
  if ((u.protocol === "https:" && u.port === "443") || (u.protocol === "http:" && u.port === "80")) {
    u.port = "";
  }
  // Drop common tracking params
  ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "ref", "fbclid", "gclid"].forEach(
    (k) => u.searchParams.delete(k),
  );
  let path = u.pathname.replace(/\/+$/, "");
  if (!path) path = "";
  u.pathname = path || "/";
  // Prefer origin without trailing slash for homepage
  if (u.pathname === "/") return `${u.origin}/`;
  return `${u.origin}${u.pathname}${u.search}`;
}

export function dedupeKeyFromUrl(url: string): string {
  const u = new URL(normalizeUrl(url));
  return `${u.hostname}${u.pathname}`.toLowerCase().replace(/\/+$/, "") || u.hostname;
}

export function slugify(value: string): string {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

export type ExtractedTool = {
  name?: string | null;
  publisher?: string | null;
  summary?: string | null;
  description?: string | null;
  official_url?: string | null;
  pricing_model?: string | null;
  price_display?: string | null;
  api_available?: boolean | null;
  open_source?: boolean | null;
  local_available?: boolean | null;
  platforms?: string[] | null;
  categories?: string[] | null;
  type?: string | null;
  keywords?: string[] | null;
  strengths?: string[] | null;
  limits?: string[] | null;
  audience?: string[] | null;
  source_url?: string | null;
};

const ALLOWED_PRICING = new Set(["Free", "Freemium", "Paid", "Open source", "Not disclosed"]);
const ALLOWED_TYPES = new Set([
  "Tool",
  "Model",
  "Agent",
  "API",
  "Platform",
  "Extension",
  "Framework",
  "Open source",
]);

export function sanitizeExtracted(raw: ExtractedTool, fallbackUrl: string): ExtractedTool {
  const pricing = raw.pricing_model && ALLOWED_PRICING.has(raw.pricing_model)
    ? raw.pricing_model
    : "Not disclosed";
  const type = raw.type && ALLOWED_TYPES.has(raw.type) ? raw.type : "Tool";

  return {
    name: raw.name?.trim() || null,
    publisher: raw.publisher?.trim() || null,
    summary: raw.summary?.trim() || null,
    description: raw.description?.trim() || null,
    official_url: raw.official_url?.trim() || fallbackUrl,
    pricing_model: pricing,
    price_display: raw.price_display?.trim() || "To verify",
    api_available: typeof raw.api_available === "boolean" ? raw.api_available : null,
    open_source: typeof raw.open_source === "boolean" ? raw.open_source : null,
    local_available: typeof raw.local_available === "boolean" ? raw.local_available : null,
    platforms: Array.isArray(raw.platforms) ? raw.platforms.filter(Boolean) : [],
    categories: Array.isArray(raw.categories) ? raw.categories.filter(Boolean) : [],
    type,
    keywords: Array.isArray(raw.keywords) ? raw.keywords.filter(Boolean) : [],
    strengths: Array.isArray(raw.strengths) ? raw.strengths.filter(Boolean) : [],
    limits: Array.isArray(raw.limits) ? raw.limits.filter(Boolean) : [],
    audience: Array.isArray(raw.audience) ? raw.audience.filter(Boolean) : [],
    source_url: raw.source_url?.trim() || fallbackUrl,
  };
}

export function confidenceFromPayload(payload: ExtractedTool): number {
  let score = 0;
  if (payload.name) score += 0.25;
  if (payload.summary) score += 0.2;
  if (payload.description) score += 0.15;
  if (payload.publisher) score += 0.1;
  if (payload.official_url) score += 0.1;
  if (payload.categories && payload.categories.length) score += 0.1;
  if (payload.pricing_model && payload.pricing_model !== "Not disclosed") score += 0.05;
  if (payload.keywords && payload.keywords.length) score += 0.05;
  return Math.min(1, Number(score.toFixed(2)));
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";
import type { ExtractedTool } from "./normalize.ts";

const FIRECRAWL_BASE = "https://api.firecrawl.dev/v2";

const TOOL_JSON_SCHEMA = {
  type: "object",
  properties: {
    name: { type: "string" },
    publisher: { type: "string" },
    summary: { type: "string" },
    description: { type: "string" },
    official_url: { type: "string" },
    pricing_model: {
      type: "string",
      enum: ["Free", "Freemium", "Paid", "Open source", "Not disclosed"],
    },
    price_display: { type: "string" },
    api_available: { type: "boolean" },
    open_source: { type: "boolean" },
    local_available: { type: "boolean" },
    platforms: { type: "array", items: { type: "string" } },
    categories: { type: "array", items: { type: "string" } },
    type: {
      type: "string",
      enum: ["Tool", "Model", "Agent", "API", "Platform", "Extension", "Framework", "Open source"],
    },
    keywords: { type: "array", items: { type: "string" } },
    strengths: { type: "array", items: { type: "string" } },
    limits: { type: "array", items: { type: "string" } },
    audience: { type: "array", items: { type: "string" } },
    source_url: { type: "string" },
  },
  required: ["name", "summary"],
};

const EXTRACT_PROMPT = `Extract factual product information about this AI tool/product page for a discovery catalog.
Rules:
- Only use facts present on the page.
- If a field is unknown, omit it or use null. Never invent prices or capabilities.
- pricing_model must be one of: Free, Freemium, Paid, Open source, Not disclosed.
- categories should map to common AI catalog categories when possible (e.g. AI Assistants, Image Generation, Coding & Development).
- Keep summary under 200 characters. description can be longer but factual.`;

const NEWS_JSON_SCHEMA = {
  type: "object",
  properties: {
    title: { type: "string" },
    published_date: { type: "string", description: "ISO date YYYY-MM-DD when the article was published" },
    summary: { type: "string" },
    product_names: { type: "array", items: { type: "string" } },
    is_article: {
      type: "boolean",
      description: "true if this is a single news article, false if listing/index/homepage",
    },
    event_kind: {
      type: "string",
      enum: ["release", "pricing", "business", "research", "news"],
    },
  },
  required: ["title", "summary", "is_article"],
};

const NEWS_EXTRACT_PROMPT = `Extract facts from this AI / tech news page.
Rules:
- Only use facts present on the page. Never invent.
- published_date must be YYYY-MM-DD if visible (byline, timestamp, JSON-LD). Otherwise omit.
- is_article=false for listing pages, tag hubs, homepages, trackers, or “latest news” indexes.
- is_article=true only for a single news/announcement article.
- product_names: AI products/models/tools mentioned (max 5).
- summary: 1-2 factual sentences from the article.`;

async function firecrawlKey(supabase?: SupabaseClient) {
  const fromEnv = Deno.env.get("FIRECRAWL_API_KEY");
  if (fromEnv) return fromEnv;
  if (!supabase) throw new Error("FIRECRAWL_API_KEY secret is not set");
  const { data, error } = await supabase
    .from("runtime_secrets")
    .select("value")
    .eq("key", "FIRECRAWL_API_KEY")
    .maybeSingle();
  if (error) throw new Error(error.message);
  if (!data?.value) throw new Error("FIRECRAWL_API_KEY secret is not set");
  return data.value;
}

export type ScrapeResult = {
  extracted: ExtractedTool;
  markdown: string | null;
};

export async function scrapeTool(url: string, supabase?: SupabaseClient): Promise<ScrapeResult> {
  const key = await firecrawlKey(supabase);
  const res = await fetch(`${FIRECRAWL_BASE}/scrape`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      url,
      formats: [
        "markdown",
        {
          type: "json",
          prompt: EXTRACT_PROMPT,
          schema: TOOL_JSON_SCHEMA,
        },
      ],
      onlyMainContent: true,
    }),
  });

  const body = await res.json();
  if (!res.ok) {
    throw new Error(body?.error || body?.message || `Firecrawl scrape failed (${res.status})`);
  }

  const data = body?.data ?? body;
  const extracted = (data?.json ?? data?.extract ?? {}) as ExtractedTool;
  const markdown = typeof data?.markdown === "string" ? data.markdown : null;
  return { extracted, markdown };
}

export type NewsScrape = {
  title?: string;
  published_date?: string;
  summary?: string;
  product_names?: string[];
  is_article?: boolean;
  event_kind?: string;
  markdown: string | null;
};

export async function scrapeNewsArticle(url: string, supabase?: SupabaseClient): Promise<NewsScrape> {
  const key = await firecrawlKey(supabase);
  const res = await fetch(`${FIRECRAWL_BASE}/scrape`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      url,
      formats: [
        "markdown",
        {
          type: "json",
          prompt: NEWS_EXTRACT_PROMPT,
          schema: NEWS_JSON_SCHEMA,
        },
      ],
      onlyMainContent: true,
    }),
  });

  const body = await res.json();
  if (!res.ok) {
    throw new Error(body?.error || body?.message || `Firecrawl scrape failed (${res.status})`);
  }

  const data = body?.data ?? body;
  const extracted = (data?.json ?? data?.extract ?? {}) as Record<string, unknown>;
  const markdown = typeof data?.markdown === "string" ? data.markdown : null;
  return {
    title: extracted.title ? String(extracted.title) : undefined,
    published_date: extracted.published_date ? String(extracted.published_date).slice(0, 10) : undefined,
    summary: extracted.summary ? String(extracted.summary) : undefined,
    product_names: Array.isArray(extracted.product_names)
      ? extracted.product_names.map(String).slice(0, 5)
      : undefined,
    is_article: typeof extracted.is_article === "boolean" ? extracted.is_article : undefined,
    event_kind: extracted.event_kind ? String(extracted.event_kind) : undefined,
    markdown,
  };
}

export type SearchHit = { url: string; title?: string; description?: string };

export async function searchNewTools(
  query: string,
  limit = 8,
  supabase?: SupabaseClient,
  options: { tbs?: string } = {},
): Promise<SearchHit[]> {
  const key = await firecrawlKey(supabase);
  const payload: Record<string, unknown> = {
    query,
    limit,
  };
  // Google-style time filter when supported by Firecrawl search
  if (options.tbs) payload.tbs = options.tbs;

  const res = await fetch(`${FIRECRAWL_BASE}/search`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });

  const body = await res.json();
  if (!res.ok) {
    throw new Error(body?.error || body?.message || `Firecrawl search failed (${res.status})`);
  }

  const web = body?.data?.web ?? body?.web ?? body?.data ?? [];
  if (!Array.isArray(web)) return [];

  return web
    .map((item: Record<string, unknown>) => ({
      url: String(item.url ?? item.link ?? ""),
      title: item.title ? String(item.title) : undefined,
      description: item.description ? String(item.description) : undefined,
    }))
    .filter((h: SearchHit) => Boolean(h.url));
}
